  level(tMs: number): number {
    this.prune(tMs);
    return clamp(this.peaks.length / this.t.shakePeaksForFull, 0, 1);
  }

  private prune(tMs: number): void {
    let first = this.peaks[0];
    while (first !== undefined && tMs - first > this.t.shakeWindowMs) {
      this.peaks.shift();
      first = this.peaks[0];
    }
  }
}

